  "CREATE TABLE IF NOT EXISTS social_posts (\n  id TEXT PRIMARY KEY,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  title TEXT,\n  body_ar TEXT,\n  body_en TEXT,\n  link_url TEXT,\n  cta_label TEXT,\n  hashtags TEXT,\n  media_json TEXT NOT NULL DEFAULT '[]',\n  language TEXT NOT NULL DEFAULT 'ar' CHECK (language IN ('ar', 'en', 'both')),\n  status TEXT NOT NULL DEFAULT 'draft',\n  version INTEGER NOT NULL DEFAULT 1,\n  scheduled_at TEXT,\n  created_by TEXT,\n  submitted_by TEXT,\n  submitted_at TEXT,\n  approved_by TEXT,\n  approved_at TEXT,\n  published_at TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n)",
  "CREATE INDEX IF NOT EXISTS idx_social_posts_company ON social_posts(company_id, status, created_at)",
  "CREATE TABLE IF NOT EXISTS social_post_versions (\n  id TEXT PRIMARY KEY,\n  post_id TEXT NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  version INTEGER NOT NULL,\n  snapshot_json TEXT NOT NULL,\n  created_by TEXT,\n  reason TEXT,\n  created_at TEXT NOT NULL,\n  UNIQUE (post_id, version)\n)",
  "CREATE TABLE IF NOT EXISTS social_post_targets (\n  id TEXT PRIMARY KEY,\n  post_id TEXT NOT NULL REFERENCES social_posts(id) ON DELETE CASCADE,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  connection_id TEXT REFERENCES social_connections(id) ON DELETE SET NULL,\n  platform TEXT NOT NULL,\n  account_name TEXT,\n  adapted_text TEXT,\n  adapted_json TEXT NOT NULL DEFAULT '{}',\n  status TEXT NOT NULL DEFAULT 'blocked',\n  external_id TEXT,\n  external_url TEXT,\n  error_code TEXT,\n  error_message TEXT,\n  attempts INTEGER NOT NULL DEFAULT 0,\n  last_attempt_at TEXT,\n  published_at TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  UNIQUE (post_id, platform, connection_id)\n)",
  "CREATE INDEX IF NOT EXISTS idx_social_targets_post ON social_post_targets(post_id)",
  "CREATE INDEX IF NOT EXISTS idx_social_targets_company ON social_post_targets(company_id, status)",
  "CREATE TABLE IF NOT EXISTS social_post_metrics (\n  target_id TEXT PRIMARY KEY REFERENCES social_post_targets(id) ON DELETE CASCADE,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  impressions INTEGER,\n  reach INTEGER,\n  clicks INTEGER,\n  likes INTEGER,\n  comments INTEGER,\n  shares INTEGER,\n  saves INTEGER,\n  source TEXT NOT NULL DEFAULT 'platform api',\n  fetched_at TEXT NOT NULL,\n  note TEXT\n)",
  "CREATE TABLE IF NOT EXISTS social_jobs (\n  id TEXT PRIMARY KEY,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  target_id TEXT NOT NULL REFERENCES social_post_targets(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL DEFAULT 'publish_target',\n  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'running', 'done', 'failed', 'cancelled')),\n  run_at TEXT NOT NULL,\n  attempts INTEGER NOT NULL DEFAULT 0,\n  max_attempts INTEGER NOT NULL DEFAULT 3,\n  locked_at TEXT,\n  last_error TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  UNIQUE (target_id)\n)",
  "CREATE INDEX IF NOT EXISTS idx_social_jobs_due ON social_jobs(state, run_at)",
  "CREATE TABLE IF NOT EXISTS social_events (\n  id TEXT PRIMARY KEY,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  connection_id TEXT,\n  post_id TEXT,\n  target_id TEXT,\n  kind TEXT NOT NULL,\n  detail TEXT,\n  actor_user_id TEXT,\n  created_at TEXT NOT NULL\n)",
  "CREATE INDEX IF NOT EXISTS idx_social_events_company ON social_events(company_id, created_at)",
  "ALTER TABLE social_posts ADD COLUMN review_note TEXT",
  "ALTER TABLE social_posts ADD COLUMN reviewed_by TEXT",
  "ALTER TABLE social_posts ADD COLUMN reviewed_at TEXT",
  "CREATE TABLE IF NOT EXISTS tracking_links (\n  id TEXT PRIMARY KEY,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  campaign_id TEXT REFERENCES campaigns(id) ON DELETE SET NULL,\n  post_id TEXT REFERENCES social_posts(id) ON DELETE SET NULL,\n  platform TEXT,\n  code TEXT NOT NULL UNIQUE,\n  label TEXT NOT NULL,\n  destination_url TEXT NOT NULL,\n  utm_source TEXT,\n  utm_medium TEXT,\n  utm_campaign TEXT,\n  utm_content TEXT,\n  utm_term TEXT,\n  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused')),\n  created_by TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n)",
  "CREATE INDEX IF NOT EXISTS idx_tracking_links_company ON tracking_links(company_id, created_at)",
  "CREATE INDEX IF NOT EXISTS idx_tracking_links_campaign ON tracking_links(company_id, campaign_id)",
  "CREATE TABLE IF NOT EXISTS tracking_events (\n  id TEXT PRIMARY KEY,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  link_id TEXT REFERENCES tracking_links(id) ON DELETE SET NULL,\n  lead_id TEXT REFERENCES leads(id) ON DELETE SET NULL,\n  post_id TEXT,\n  campaign_id TEXT,\n  kind TEXT NOT NULL\n    CHECK (kind IN ('click', 'page_view', 'whatsapp_click', 'call_click', 'form_submit', 'lead')),\n  platform TEXT,\n  occurred_at TEXT NOT NULL,\n  period_date TEXT NOT NULL,\n  visitor_hash TEXT NOT NULL,\n  country TEXT,\n  device TEXT,\n  referrer_host TEXT,\n  metadata_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL\n)",
  "CREATE INDEX IF NOT EXISTS idx_tracking_events_company_date ON tracking_events(company_id, period_date)",
  "CREATE INDEX IF NOT EXISTS idx_tracking_events_link ON tracking_events(link_id, kind)",
  "CREATE INDEX IF NOT EXISTS idx_tracking_events_campaign ON tracking_events(company_id, campaign_id)",
  "ALTER TABLE leads ADD COLUMN tracking_link_id TEXT",
  "CREATE TABLE IF NOT EXISTS poster_drafts (\n  id TEXT PRIMARY KEY,\n  company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,\n  title TEXT NOT NULL,\n  headline TEXT NOT NULL,\n  subhead TEXT,\n  cta TEXT,\n  template TEXT NOT NULL DEFAULT 'bold' CHECK (template IN ('bold', 'minimal', 'offer')),\n  size_key TEXT NOT NULL,\n  width INTEGER NOT NULL,\n  height INTEGER NOT NULL,\n  brand_color TEXT NOT NULL DEFAULT '#0f766e',\n  language TEXT NOT NULL DEFAULT 'ar' CHECK (language IN ('ar', 'en')),\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'archived')),\n  version INTEGER NOT NULL DEFAULT 1,\n  created_by TEXT,\n  approved_by TEXT,\n  approved_at TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n)",
  "CREATE INDEX IF NOT EXISTS idx_posters_company ON poster_drafts(company_id, created_at)",
